function exonerablePublico(D){ if(D<=0) return 0; return Math.min(D,5000) + Math.min(Math.max(D-5000,0)*0.5, 5000); }
function calcCreditoPublico(creditos, epiPrevia){
  const PUB=['aeat','tgss','ccaa','local','otro_publico'];
  const NOEX=['multa_penal','sancion_muy_grave'];
  const orden={ordinario:0, privilegio_general:1, privilegio_especial:2};
  const res={}; const pub=creditos.filter(c=>PUB.includes(c.tipo_acreedor));
  for(const c of pub){ (res[c.acreedor] ||= {creditos:[],exonerable:0,no_exonerable:0}).creditos.push(c); }
  for(const [acr,r] of Object.entries(res)){
    if(epiPrevia){ r.creditos.forEach(c=>{c.exonerado=0;c.no_exonerado=c.importe;}); r.no_exonerable=r.creditos.reduce((s,c)=>s+c.importe,0); continue; }
    const sub=r.creditos.filter(c=>c.clase==='subordinado');
    sub.forEach(c=>{ const ex=NOEX.includes(c.concepto)?0:c.importe; c.exonerado=ex; c.no_exonerado=c.importe-ex; });
    const noSub=r.creditos.filter(c=>c.clase!=='subordinado' && !NOEX.includes(c.concepto))
      .sort((a,b)=> (orden[a.clase]-orden[b.clase]) || (new Date(a.fecha_nacimiento)-new Date(b.fecha_nacimiento)));
    const D=noSub.reduce((s,c)=>s+c.importe,0); let E=exonerablePublico(D); r.exonerable_489_1_5=E;
    for(const c of noSub){ const ex=Math.min(c.importe,E); c.exonerado=+ex.toFixed(2); c.no_exonerado=+(c.importe-ex).toFixed(2); E-=ex; }
    r.creditos.filter(c=>c.clase!=='subordinado' && NOEX.includes(c.concepto)).forEach(c=>{c.exonerado=0;c.no_exonerado=c.importe;});
    r.exonerable=r.creditos.reduce((s,c)=>s+(c.exonerado||0),0); r.no_exonerable=r.creditos.reduce((s,c)=>s+(c.no_exonerado||0),0);
  }
  return res;
}

